using System;using System.IO;using System.Collections.Generic;using ReplierDesktop;
public static class ContextChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 public static int Main(){try{var v=new Video{Title="결과 공개"};var e=new[]{new KeyValuePair<string,CaptionCue>("c0",new CaptionCue{Text="아직 결과를 기다리고 있습니다."}),new KeyValuePair<string,CaptionCue>("c1",new CaptionCue{Text="승인이 나서 다음 달에 출시됩니다."})};
 Check(!WholeCommentGrounding.Parse("{\"supported\":true,\"source\":0,\"quote\":\"다음 달에 출시됩니다.\"}","반가워요",v,e).Supported,"quote from another source cannot validate a wrong source index");
 Check(WholeCommentGrounding.Parse("{\"supported\":true,\"source\":1,\"quote\":\"다음 달에 출시됩니다.\"}","출시 기대돼요",v,e).Supported,"exact observed event supports a reaction without identical wording");
 bool rejected=false;try{ConnectionRubric.ParseContext("{\"evaluated_comment\":\"출시 기대돼요\",\"focus\":\"승인 결과\",\"explanation\":\"출시 기대 반응\",\"quote\":\"다음 달에 출시됩니다.\",\"connection\":\"direct_reaction\",\"evidence\":0}",new CommentSuggestion{Text="출시 기대돼요"},e,"viewer");}catch(InvalidDataException){rejected=true;}Check(rejected,"relevance review must bind its actual quotation to its selected source");
 var result=ConnectionRubric.ParseContext("{\"evaluated_comment\":\"출시 기대돼요\",\"focus\":\"승인 결과\",\"explanation\":\"출시 일정에 기대하는 직접 반응\",\"quote\":\"다음 달에 출시됩니다.\",\"connection\":\"direct_reaction\",\"evidence\":1}",new CommentSuggestion{Text="출시 기대돼요"},e,"viewer");Check(result.Score==45&&result.Reason.Contains("출시 일정"),"reason is visible while numeric rubric stays unchanged");
 Check(ReferenceGrounding.Parse("{\"word_kinds\":[{\"id\":0,\"kind\":\"ordinary_expression\",\"identity\":\"none\"},{\"id\":1,\"kind\":\"ordinary_expression\",\"identity\":\"none\"}]}",new[]{"상황","출시"},"다른 말로 표현한 원문").Supported,"ordinary expressions do not require literal occurrence");
 rejected=false;try{ReferenceGrounding.Parse("{\"word_kinds\":[{\"id\":0,\"kind\":\"explicit_reference\",\"identity\":\"none\"}]}",new[]{"낯선말"},"원문");}catch(InvalidDataException){rejected=true;}Check(rejected,"unfamiliar spelling alone cannot establish a named identity");Check(ReferenceGrounding.ParseNames("{\"references\":[]}","출시가 기다려져요. 상황이 달라졌네요","예정이 확정됐다").Supported,"ordinary prose is not sent as a list of suspicious unmatched words");
 Check(!ReferenceGrounding.ParseNames("{\"references\":[{\"name\":\"네뷸라\",\"identity\":\"product\"}]}","네뷸라 차량 예쁘네요","루멘 차량을 소개합니다").Supported,"actual name extraction still rejects an unobserved product identity");
 rejected=false;try{ReferenceGrounding.ParseNames("{\"references\":[{\"name\":\"없는이름\",\"identity\":\"product\"}]}","상황이 달라졌네요","원문");}catch(InvalidDataException){rejected=true;}Check(rejected,"name extractor cannot invent a name absent from the comment");
 var relation="{\"evaluated_comment\":\"출시 기대돼요\",\"target\":\"출시\",\"focus\":\"출시 일정 발표\",\"quote\":\"다음 달에 출시됩니다.\",\"evidence\":1,\"source_role\":\"central_event\",\"response\":\"reaction\",\"conflicts\":false,\"explanation\":\"발표된 일정에 기대하는 반응\"}";
 Check(ConnectionRubric.ParseRelation(relation,new CommentSuggestion{Text="출시 기대돼요"},e,"viewer").Score==45,"short emotion with an actual central event is a direct reaction, not an ungrounded generic feeling");
 Check(ConnectionRubric.ParseRelation(relation.Replace("central_event","supporting_example"),new CommentSuggestion{Text="출시 기대돼요"},e,"viewer").Score==36,"response to an illustrative example retains a distinct partial-relation score");
 Check(ConnectionRubric.ParseRelation(relation.Replace("central_event","no_target"),new CommentSuggestion{Text="출시 기대돼요"},e,"viewer").Score==0,"no actual response target remains ineligible without another subjective emotion veto");
 return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
